// image-source.ts: the test card's photo: the built-in sample, a viewer's own file, and the
// cover-fit drawing onto the image-area canvas.

import figureUrl from "./samples/figure.webp";

/** A decoded image the card can draw. */
export type CardImage = HTMLImageElement | ImageBitmap;

/** A built-in sample image. */
export interface SampleImage {
  /** Stable id, also used as the card's key. */
  id: string;
  /** Accessible name of its thumbnail button. */
  label: string;
  /** URL of the image file. */
  url: string;
}

/** The built-in samples. The figure was generated by the project author (MIT, like the repo). */
export const SAMPLE_IMAGES: readonly SampleImage[] = [
  { id: "figure", label: "Sample: chrome figure", url: figureUrl },
];

/** The message shown when a chosen or dropped file cannot be used. */
export const NOT_AN_IMAGE = "That file is not an image.";

/** The spec caps the canvas pixel ratio at 2 and keeps at least 160 px. */
const MAX_PIXEL_RATIO = 2;
const MIN_SIZE = 160;

/** A rectangle in pixels. */
export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * The source rectangle that covers a target of the given ratio: the largest centered part of
 * the image with that ratio.
 *
 * @param width - Image width in pixels.
 * @param height - Image height in pixels.
 * @param ratio - The target's width divided by its height.
 * @returns The source rectangle.
 */
export function coverRect(width: number, height: number, ratio: number): Rect {
  // Too wide for the target: use the full height and crop the sides; else the reverse.
  if (width / height > ratio) {
    const cropped = height * ratio;
    return { x: (width - cropped) / 2, y: 0, width: cropped, height };
  }
  const cropped = width / ratio;
  return { x: 0, y: (height - cropped) / 2, width, height: cropped };
}

/**
 * Sizes a canvas to its CSS width times the pixel ratio (capped at 2, at least 160 px wide), with
 * the height from the given ratio. The height is computed, not read, so it matches the ratio
 * exactly. Side effects: sets width and height, which clears the canvas.
 *
 * @param canvas - The laid-out canvas.
 * @param ratio - Width divided by height.
 * @param pixelRatio - The device pixel ratio.
 * @returns The canvas size in canvas pixels.
 */
export function sizeCanvas(
  canvas: HTMLCanvasElement,
  ratio: number,
  pixelRatio: number,
): { width: number; height: number } {
  const scale = Math.min(Math.max(pixelRatio, 1), MAX_PIXEL_RATIO);
  const width = Math.max(Math.round(canvas.clientWidth * scale), MIN_SIZE);
  const height = Math.max(Math.round(width / ratio), 1);
  canvas.width = width;
  canvas.height = height;
  return { width, height };
}

/**
 * Draws an image cover-fit on white (transparent parts read as light, as the grid sampling
 * expects). Side effects: resizes and redraws the canvas.
 *
 * @param canvas - The image-area canvas, already laid out.
 * @param image - The decoded image.
 * @param ratio - The image area's width divided by its height.
 * @param pixelRatio - The device pixel ratio.
 */
export function drawImageCover(
  canvas: HTMLCanvasElement,
  image: CardImage,
  ratio: number,
  pixelRatio: number,
): void {
  const { width, height } = sizeCanvas(canvas, ratio, pixelRatio);
  const context = canvas.getContext("2d");
  if (!context) return;
  context.fillStyle = "#ffffff";
  context.fillRect(0, 0, width, height);
  const source = coverRect(image.width, image.height, ratio);
  context.imageSmoothingQuality = "high";
  context.drawImage(image, source.x, source.y, source.width, source.height, 0, 0, width, height);
}

/**
 * Decodes a file the viewer chose or dropped.
 *
 * @param file - The file.
 * @returns The decoded image; rejects with {@link NOT_AN_IMAGE} for anything else.
 */
export async function loadImageFile(file: Blob): Promise<ImageBitmap> {
  if (!file.type.startsWith("image/")) throw new Error(NOT_AN_IMAGE);
  try {
    return await createImageBitmap(file);
  } catch {
    // A file named like an image that does not decode.
    throw new Error(NOT_AN_IMAGE);
  }
}

/**
 * Loads and decodes an image URL, such as a sample.
 *
 * @param url - The image URL.
 * @returns The decoded image element.
 */
export async function loadImageUrl(url: string): Promise<HTMLImageElement> {
  const image = new Image();
  image.src = url;
  await image.decode();
  return image;
}
